import{_ as t,o as a,c as n,ap as i}from"./chunks/framework.CuFS6FqL.js";const p=JSON.parse('{"title":"Self-evaluation questionnaire","description":"Reflect on your technical and social skills as a pentester. Results are for personal development only—not used for salary, bonuses, or job classification.","frontmatter":{"title":"Self-evaluation questionnaire","description":"Reflect on your technical and social skills as a pentester. Results are for personal development only—not used for salary, bonuses, or job classification."},"headers":[],"relativePath":"organization/human-resources/self-evaluation.md","filePath":"organization/human-resources/self-evaluation.md"}'),o={name:"organization/human-resources/self-evaluation.md"};function r(s,e,l,c,d,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/self-evaluation.md for this page in Markdown format</div><h1 id="self-evaluation-questionnaire" tabindex="-1">Self-evaluation questionnaire <a class="header-anchor" href="#self-evaluation-questionnaire" aria-label="Permalink to &quot;Self-evaluation questionnaire&quot;">​</a></h1><p>This self-evaluation questionnaire should help you identifying your strengths and weaknesses. We will <strong>not</strong> use the results for salary, job classification, bonuses, reference letters etc.</p><ul><li>If you find a question ambiguous or unclear, please mark it, so we can improve it.</li><li>This questionnaire might imply things that might be expected from you. <ul><li>&quot;I didn&#39;t know you expect this from me.&quot;, &quot;I didn&#39;t know I&#39;m allowed to do this.&quot;</li><li>Let us discuss this!</li></ul></li><li>If you think you can improve in some points, but you are missing guidance or documentation, please let us know.</li><li>We suggest that one of the founders keeps your filled-out questionnaire and returns it you when we fill out the questionnaire the next time. <ul><li>This is optional; you can disard it or keep it yourself.</li><li>We keep it for the future &quot;you&quot;. We will not evaluate it, apply any scores, etc.</li><li>We will discard or return it if you leave the company.</li></ul></li></ul><h2 id="after-filling-out-the-questionnaire" tabindex="-1">After filling out the questionnaire <a class="header-anchor" href="#after-filling-out-the-questionnaire" aria-label="Permalink to &quot;After filling out the questionnaire&quot;">​</a></h2><ul><li>Select one questionnaire-section (e.g., &quot;Report Writing&quot;, etc.) in which you want to improve: ________________________________________________________</li><li>How can we as a company or as a team support you with this? ________________________________________________________</li><li>Present your results to one of your colleagues (by selecting one or by drawing lots). <ul><li>Seek honest feedback.</li></ul></li><li>Optional: Share your thoughts with the team.</li></ul><div style="break-after:page;"></div><h2 id="technical-competence" tabindex="-1">Technical Competence <a class="header-anchor" href="#technical-competence" aria-label="Permalink to &quot;Technical Competence&quot;">​</a></h2><h3 id="web-pentesting" tabindex="-1">Web Pentesting <a class="header-anchor" href="#web-pentesting" aria-label="Permalink to &quot;Web Pentesting&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I know at least the OWASP Top 10 and can identify simple vulnerabilities<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I conduct web pentests independently and analyze complex vulnerabilities<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I develop new testing methods<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I share my knowledge and train my colleagues in web pentesting</p><h3 id="active-directory-internal-infrastructures" tabindex="-1">Active Directory / Internal Infrastructures <a class="header-anchor" href="#active-directory-internal-infrastructures" aria-label="Permalink to &quot;Active Directory / Internal Infrastructures&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I understand basic AD attack concepts<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I know basic concepts of Entra ID and hybrid identity environments<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I conduct AD pentests independently and analyze complex attacks<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I have in-depth AD and Entra ID knowledge and develop concepts and defense strategies for customers<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I share knowledge and train colleagues in AD/Entra ID pentesting</p><h3 id="tools-automation" tabindex="-1">Tools &amp; Automation <a class="header-anchor" href="#tools-automation" aria-label="Permalink to &quot;Tools &amp; Automation&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I use standard tools confidently<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I automate recurring test steps with self-developed scripts/procedures (including Burp features)<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I develop my own testing approaches beyond automated scanners or existing tools</p><h3 id="report-writing" tabindex="-1">Report Writing <a class="header-anchor" href="#report-writing" aria-label="Permalink to &quot;Report Writing&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I document simple and recurring findings in the report (e.g., session not invalidated after logout)<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I document complex finding descriptions well-structured, clearly and independently<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I write different report sections for different target audiences (developers, admins, management)<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I deliver solid presentations for technical audiences<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I deliver solid presentations for management audiences<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I describe findings technically correctly and reproducibly<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I formulate findings in a way that customers can understand<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I can explain risks in business-oriented terms<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - My remediation recommendations are concrete and reasonably actionable<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I process peer review feedback purposefully and learn from it<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I start writing the report early, so I can finish the project in time</p><h3 id="engagement-process" tabindex="-1">Engagement &amp; Process <a class="header-anchor" href="#engagement-process" aria-label="Permalink to &quot;Engagement &amp; Process&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I understand the scope, boundaries, and approach of a pentest<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I follow the <a href="/pentesting-manual/operation-rules">pentesting operation rules</a><br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I conduct kickoffs and prepare pentests<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I communicate critical findings promptly via the agreed channels<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I schedule mid-test check-ins early<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I conduct mid-test check-ins<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I own the entire engagement flow, including retest and remediation documentation<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I prepare findings during the test, so a later retest is possible without rebuilding the attack chain<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I document findings precisely enough that a retest can be performed (including by another person)</p><h2 id="social-competence" tabindex="-1">Social Competence <a class="header-anchor" href="#social-competence" aria-label="Permalink to &quot;Social Competence&quot;">​</a></h2><h3 id="self-responsibility" tabindex="-1">Self-Responsibility <a class="header-anchor" href="#self-responsibility" aria-label="Permalink to &quot;Self-Responsibility&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I complete tasks according to instructions<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I identify blockers early and report them when needed<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I seek feedback proactively<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I meet deadlines<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I plan projects independently, structure and prioritize tasks<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I own projects end-to-end: prioritize, make decisions, organize execution<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I identify and report weaknesses in our team and internal processes<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I suggest improvements to our team and internal processes</p><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I communicate clearly and give constructive feedback<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I explain technical topics in an understandable way<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I conduct myself confidently in customer meetings<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I can argue findings convincingly<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I ask follow-up questions when something is unclear</p><h3 id="teamwork" tabindex="-1">Teamwork <a class="header-anchor" href="#teamwork" aria-label="Permalink to &quot;Teamwork&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I share knowledge actively within the team<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I work actively with colleagues on projects<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I give constructive feedback<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I accept feedback<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I work solution-oriented in projects in the customer&#39;s interest<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I lead project teams and/or provide mentoring<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - My colleages enjoy working on projects with me</p><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I fix minor errors in the handbook immediately<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I add topics to existing handbook pages<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I create new handbook pages on new topics</p><h3 id="customer-orientation" tabindex="-1">Customer Orientation <a class="header-anchor" href="#customer-orientation" aria-label="Permalink to &quot;Customer Orientation&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I have a basic understanding of customer requirements<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I advise customers actively and adapt my communication to the target audience<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I build long-term customer relationships and provide strategic advice</p><h3 id="ethics-confidentiality" tabindex="-1">Ethics &amp; Confidentiality <a class="header-anchor" href="#ethics-confidentiality" aria-label="Permalink to &quot;Ethics &amp; Confidentiality&quot;">​</a></h3><p>◯ 🌱 ◯ 🌿 ◯ 🌳 - I treat customer data and findings confidentially and in accordance with agreements<br> ◯ 🌱 ◯ 🌿 ◯ 🌳 - I strictly adhere to scope boundaries and test only with explicit approval</p><h2 id="one-last-thing" tabindex="-1"><em>...one last thing</em> <a class="header-anchor" href="#one-last-thing" aria-label="Permalink to &quot;*...one last thing*&quot;">​</a></h2><p>Is there anything you cannot implement due to external factors, which should be improved?<br> This could be something like, missing documentation, gatekeeping superiors, hindering culture, missing budget, bad processes, etc.</p><p>What would you like to improve? ________________________________________________________<br> Please approach us, so we can improve.</p>',34)])])}const _=t(o,[["render",r]]);export{p as __pageData,_ as default};
